// Hand-coded ground truth for OpenServ's own example policy
// (docs.openserv.ai/blog/the-reasoning-problem). This is the flowchart a
// human support lead would apply, encoded directly -- no model involved.
// eval/cases.json's `expected` field is generated by calling this function,
// never written by hand.

export { REFERENCE_POLICY } from "../lib/policy.js";

/**
 * @param {{order_total:number, days_since_delivery:number, is_digital:boolean,
 *          download_failed:boolean, paid_with_store_credit:boolean}} order
 * @returns {{decision:"approve"|"decline"|"escalate", refund_amount:number,
 *            refund_to:"original_payment"|"store_credit"|"none"}}
 */
export function reference(order) {
  const {
    order_total,
    days_since_delivery,
    is_digital,
    download_failed,
    paid_with_store_credit,
  } = order;

  // Digital goods are non-refundable unless the download failed.
  if (is_digital && !download_failed) {
    return { decision: "decline", refund_amount: 0, refund_to: "none" };
  }

  // Refunds are allowed within 30 days of delivery.
  if (days_since_delivery > 30) {
    return { decision: "decline", refund_amount: 0, refund_to: "none" };
  }

  // Orders paid with store credit are refunded to store credit only.
  const refund_to = paid_with_store_credit ? "store_credit" : "original_payment";

  // Any refund over 200 needs a manager to approve it before it is issued.
  if (order_total > 200) {
    return { decision: "escalate", refund_amount: order_total, refund_to };
  }

  return { decision: "approve", refund_amount: order_total, refund_to };
}
